# aeneid-060 (VIII.306-406): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Per Pallanteum. Venus et Volcanus'
PART = "Evander's Walk and Vulcan's Promise (VIII.306–406)"
TITLE_EN = "Evander's Walk and Vulcan's Promise — Aeneid VIII.306–406"
ABOUT = ("The rites of Hercules are over, and the company walks back to the town. Old Evander keeps Aeneas and his own son Pallas "
"beside him and lightens the way with talk, and Aeneas, delighted, asks about everything he sees. Evander tells the story of the "
"place: woodland once held by Fauns and Nymphs and a wild race of men born from tree-trunks, until Saturn, driven from heaven by "
"Jupiter, came and hid here, gave them laws and named the land Latium, and ruled a Golden Age that sank by degrees into greed "
"and war; then came new peoples and kings, the river took a new name, and last of all Evander himself, an exile brought here by "
"fate and his prophetic mother Carmentis. Then he shows the sights, and they are the sights of Rome before Rome: the Carmental "
"Gate, the grove Romulus would make his Asylum, the cave of the Lupercal, the Argiletum, the Tarpeian Rock and the Capitol, "
"golden in Virgil's day and thorn-scrub in Evander's, where a god, perhaps Jupiter, is felt to dwell; the ruins of two towns on "
"the Janiculum and the Capitol; cattle lowing where the Forum and the smart quarter of the Carinae would stand. At his humble "
"house Evander bids his guest dare to despise riches, as Hercules did, and gives him a bed of leaves and a bearskin. Night falls. "
"Venus, afraid for her son, goes to her husband Vulcan in their golden bedroom and, as Thetis and Aurora did before her for "
"Achilles and Memnon, asks him to forge arms for Aeneas; she wins him with an embrace, and he promises all that fire and his "
"art can do. The arms he makes will be the shield of Book VIII's close.")

U = [
(307, 'referunt.',
 "Thereupon they all, the divine things being finished, to the city\nbetake themselves.",
 "Then, the sacred rites completed, they all made their way back to the city.",
 """A new paragraph in Greenough. 'Exim', an old form of 'exinde', 'thereupon'. 'divinis rebus… perfectis', ablative absolute, 'the divine business having been completed', the rites at the Ara Maxima that closed the last part, framing the clause across the line. 'se… referunt', 'they carry themselves back', 'return', with 'cuncti', 'all of them', the Arcadians and the Trojans together. 'ad urbem', Evander's town of Pallanteum on the Palatine. No elisions."""),
(309, 'levabat.',
 "Went the king, beset with age,\nand as companion Aeneas close by and his son he kept\nas he walked, and with varied the way talk he lightened.",
 "The king walked on, weighed down with years, keeping Aeneas and his son close beside him as he went, and lightened the road with talk of many things.",
 """'Ibat', 'was going', the imperfect of a scene in progress, like 'tenebat' and 'levabat' after it. 'obsitus aevo', 'overgrown with age', from 'obsero', 'to sow over', 'to cover': age has spread over him like a crop. 'comitem', predicative, 'as his companion'. 'Aenean', the Greek accusative of 'Aeneas'; 'Ae-' is one long syllable, and the '-em' of 'comitem' is elided before it. 'natum', Evander's son Pallas (8.104). 'iuxta', adverb, 'close by'. 'ingrediens', 'walking', 'as he went'. 'varioque… sermone', 'with varied talk', framing 'viam', 'the road', which he 'lightens', makes seem shorter. Elision 'comit(em) Aenean'."""),
(312, 'priorum.',
 "Marvels and his ready eyes he carries all things round,\nAeneas, and is captivated by the places, and each thing, glad,\nboth asks about and hears, of men the memorials of former.",
 "Aeneas was full of wonder, and turned his quick eyes on everything about him; the places held him spellbound, and he gladly asked about each thing in turn and listened to the stories of the men of old.",
 """The print has 'miratur', lowercase after the full stop that ends 309, a misprint for 'Miratur', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'Miratur', 'marvels', placed first, with its subject 'Aeneas' held back to the start of the next line. 'facilis… oculos', accusative plural in '-is', 'ready', 'easily moving' eyes, eyes that turn wherever they are drawn. 'omnia circum', 'round all things', the preposition after its noun (anastrophe). 'capitur… locis', 'is taken', 'charmed', by the places, 'locis' ablative of means. 'singula', 'each thing', object of both verbs; 'exquiritque auditque', 'both asks and hears', the double '-que'. 'virum… priorum', 'of earlier men', framing 'monimenta', 'memorials', in apposition to 'singula'; 'virum' = 'virorum', the old short genitive plural. Elisions 'facilisqu(e) oculos', 'exquiritqu(e) auditque'."""),
(313, 'arcis:',
 "Then King Evander, of the Roman the founder citadel:",
 "Then King Evander, who founded the citadel of Rome, spoke:",
 """The verb of speaking is left out, as often before a speech ('Aeolus haec contra'). 'Euandrus', Greenough's spelling of the Greek name, Euandros, 'good man'; the Greek 'eu' is one syllable, 'Eu-an-drus'. 'Romanae conditor arcis', 'founder of the Roman citadel', framing 'conditor': Evander's town stood on the Palatine, and Virgil calls him its founder with Rome's future in view. Readers have often noticed the irony that the first 'conditor' of the Roman citadel is a Greek exile. No elisions."""),
(318, 'alebat.',
 "“These groves the native Fauns and Nymphs held,\nand a race of men from trunks and from hard oak born,\nto whom neither custom nor cultivation was, nor to yoke bulls\nor to store up wealth did they know, or to spare what was got,\nbut boughs and, harsh in its fare, hunting nourished them.",
 "“These woods were once the home of native Fauns and Nymphs, and of a race of men sprung from tree-trunks and hard oak, who had no settled ways and no tilling of the soil; they did not know how to yoke the ox, or lay up wealth, or husband what they had gained, but lived on what the branches bore and on the hard fare of the hunt.",
 """Evander's speech, his account of the place, opens here; it runs to 336. 'indigenae', 'native', 'born in the land', with both 'fauni' and 'nymphae': the Fauns are Italian woodland spirits, here a whole people of them. 'gensque virum', 'a race of men' ('virum' = 'virorum' again). 'truncis et duro robore nata', 'born from trunks and hard oak': men sprung from trees is an old story (Penelope tells the disguised Odysseus he was not born 'from an oak or a rock', Odyssey 19, from memory). 'quis' = 'quibus', dative of possession with 'erat', 'who had'. 'mos', settled custom, 'cultus', tillage and the way of life it brings. 'norant' = 'noverant', 'knew how', with three infinitives. 'componere opes', 'to put wealth together', store it up; 'parcere parto', 'to spare what was gained' ('parto', from 'pario', 'get'), to save. 'rami', 'boughs', meaning the acorns and berries they bore; 'asper victu venatus', 'hunting harsh in its food', 'victu' ablative of respect. Elisions 'nemor(a) indigenae', 'componer(e) opes', 'ram(i) atque', 'atqu(e) asper'."""),
(320, 'ademptis.',
 "First from heavenly came Saturn Olympus,\nthe arms of Jupiter fleeing and, his realms taken away, an exile.",
 "The first to come was Saturn, down from the heights of Olympus, fleeing the weapons of Jupiter, an exile stripped of his kingdom.",
 """'Primus', 'first', the first civiliser. 'aetherio… Olympo', 'from heavenly Olympus', framing the line, ablative of the place from which with 'ab'. 'Saturnus', the old Italian god identified with the Greek Kronos, whom his son Zeus (Jupiter) overthrew; the Romans told that the exiled god came to Italy. 'arma Iovis fugiens', 'fleeing the arms of Jupiter'. 'regnis… ademptis', ablative absolute, 'his realms having been taken from him'; 'exsul', 'an exile', in apposition to the subject. No elisions."""),
(323, 'oris.',
 "He the race unteachable and scattered on the mountains high\nbrought together and laws gave, and Latium to be called\npreferred, since in these he had lain hid, safe, shores.",
 "He gathered that untamed race, scattered over the high mountains, and gave them laws, and chose to call the land Latium, because he had lain hidden safe within its borders.",
 """'Is', 'he', Saturn. 'genus indocile ac dispersum', 'the unteachable and scattered race', the men of 315. 'composuit', 'put together', settled them in a community, the word picking up 'componere' (317). 'Latiumque vocari maluit', 'and preferred that (the land) be called Latium'. The name is explained from 'latuisset', 'he had lain hidden', from 'lateo': an ancient etymology, not a modern one. The subjunctive gives the reason as Saturn's own thought. 'his… tutis in oris', 'in these safe shores', 'oris' for land in general. The Latin Library prints 'tutus' for Greenough's 'tutis': with 'tutus' it is Saturn himself who was safe ('since he had lain hidden here in safety'); with 'tutis' the shores were safe. The sense comes to much the same. Elision 'indocil(e) ac'."""),
(325, 'saecula.',
 "Golden, which they tell of, under that king were\nthe ages.",
 "Under that king were the golden ages that men tell of.",
 """'Aurea… saecula', 'the golden ages', framing the sentence across the line, with 'saecula' held back to the start of 325 for weight. 'quae perhibent', 'which they speak of', 'which people tell of', the antecedent drawn into the relative clause. 'illo sub rege', 'under that king', the preposition between adjective and noun. 'fuere' = 'fuerunt', the '-ere' perfect. The Golden Age under Saturn (Kronos) is Hesiod's (Works and Days, from memory); Virgil makes Italy its home, and in Book VI Anchises promises that Augustus will bring it back to Latium (6.792–794). No elisions."""),
(327, 'habendi.',
 "Thus in tranquil the peoples in peace he ruled,\nuntil a worse little by little and discoloured age\nand of war the madness and the love came after of possessing.",
 "So he ruled his peoples in untroubled peace, until little by little a worse and tarnished age came on, and the madness of war, and the love of gain.",
 """'Sic', 'in this way', with laws and settled life. 'placida… in pace', 'in calm peace', framing 'populos'. 'regebat', imperfect, the long reign. 'deterior… ac decolor aetas', 'a worse and discoloured age', the metal of the Golden Age growing dull and base. 'donec', 'until', with the perfect indicative 'successit', 'came after', 'took its place'; the verb is singular, agreeing with the nearest of its three subjects. 'belli rabies', 'the madness of war'. 'amor… habendi', 'the love of having', 'habendi' the genitive of the gerund, framing 'successit'. The three subjects grow from a dull age to frenzy and greed. Elision 'paulat(im) ac'."""),
(329, 'tellus;',
 "Then a band Ausonian and peoples came Sicanian,\nand more often its name laid aside the Saturnian land;",
 "Then came the Ausonian bands and the Sicanian peoples, and again and again the land of Saturn put off its name;",
 """'manus Ausonia', 'the Ausonian band', the Ausones, an old people of central and southern Italy, whose name poets use for Italy as a whole. 'gentes… Sicanae', 'the Sicanian peoples', thought to have lived in Italy before they crossed to Sicily. 'venere' = 'venerunt'. 'saepius', 'more often', 'again and again': each new people renamed the land, so that it was Saturnia, Ausonia, Hesperia, Oenotria, Italia in turn. 'posuit nomen', 'laid aside its name'. 'Saturnia tellus', 'the land of Saturn', a name for Italy (as in Georgics 2, from memory). Elision 'Ausoni(a) et'."""),
(332, 'nomen;',
 "then kings, and harsh, of huge body, Thybris,\nfrom whom afterwards we Italians the river by the name of Thybris\nhave called; lost its true the ancient Albula name;",
 "then came kings, and fierce Thybris of giant frame, after whom we Italians have since called our river Thybris, and the old Albula lost its true name;",
 """'tum reges', 'then (came) kings', the verb carried over from 'venere'. 'asperque immani corpore Thybris', 'and Thybris, fierce, of huge body', 'immani corpore' an ablative of description. Thybris is here a king who gave his name to the Tiber (Livy tells of a king of Alba, Tiberinus, drowned in the river, from memory). 'a quo… cognomine', 'from whom as a name', 'after whom'. 'Itali… diximus', 'we Italians called': Evander, though a Greek, counts himself among the Italians. 'fluvium… Thybrim', 'the river (as) Thybris', a predicate accusative, with the Greek accusative ending '-im'. 'amisit… Albula nomen', 'Albula lost its name', with no connective (asyndeton): 'Albula', 'the whitish', was the river's older name. 'verum vetus', 'its true, old (name)'. Elision 'asperqu(e) immani'."""),
(336, 'Apollo.',
 "Me, driven from my fatherland and of the sea the furthest bounds following,\nFortune all-powerful and inescapable fate\nin these placed places, and of my mother drove me the dread\nCarmentis, the nymph, warnings, and the god, my sponsor, Apollo.”",
 "As for me, driven from my homeland and following the sea to its furthest bounds, all-powerful Fortune and inescapable fate set me down in this place, and I was urged on by the dread warnings of my mother, the nymph Carmentis, and by the authority of the god Apollo.”",
 """The print has no closing mark after 'Apollo.' at the end of 336, a misprint for 'Apollo.”', corrected here: Evander's speech, opened at 314, ends with this line, as 'Vix ea dicta' (337) shows; t keeps the print, because t must match the pinned source; l and i close the speech. 'me', object of both 'posuere' and 'egere', put first: Evander comes last in his history of the land. 'pulsum patria', 'driven from my country', ablative of separation; 'pelagique extrema sequentem', 'following the furthest bounds of the sea'. 'Fortuna omnipotens et ineluctabile fatum', 'all-powerful Fortune and fate that cannot be wrestled out of' ('in-' + 'eluctor'). 'posuere' = 'posuerunt', 'egere' = 'egerunt', 'drove (me)'. 'matris… tremenda… Carmentis nymphae monita', 'the awe-inspiring warnings of my mother, the nymph Carmentis', framing the clause; 'Carmentis' is genitive (nominative 'Carmentis', also 'Carmenta'), the prophetess-mother of Evander. 'deus auctor Apollo', 'Apollo, the god, as sponsor', 'auctor' the one whose authority stands behind a venture. Elisions 'pelagiqu(e) extrema', 'Fortun(a) omnipotens', 'matrisqu(e) egere', 'monit(a) et'."""),
(337, 'dicta:',
 "Scarcely these things said:",
 "Scarcely had he spoken these words,",
 """'Vix ea dicta', 'scarcely (were) these things said', with 'sunt' or 'erant' left out, a common formula of transition: no sooner had he finished than he was on the move. 'ea', neuter plural, 'these things', the words of the speech. Here 'dehinc', which follows, has its two syllables, 'de-hinc' (at 1.131 Virgil makes it one). No elisions."""),
(341, 'Pallanteum.',
 "then going forward he shows both the altar\nand the Carmental, by the Romans by name, gate,\nwhich they call so, of the nymph the ancient honour, Carmentis,\nthe prophesying seer, who sang first of the future\nAeneadae, great, and noble Pallanteum.",
 "when he moved on and showed him the altar and the gate the Romans call the Carmental Gate, an ancient tribute to the nymph Carmentis, the seer who spoke the future, who first foretold the greatness of the sons of Aeneas and the glory of Pallanteum.",
 """'dehinc', 'then', 'next'. 'progressus', 'having gone forward'. 'monstrat… et aram et… portam', 'shows both the altar and the gate': the altar of Carmentis and the Porta Carmentalis, a gate in the old wall of Rome at the foot of the Capitol. 'Carmentalem Romani nomine portam quam memorant', 'the gate which the Romans call by the name Carmental', the antecedent drawn into the relative clause and the words framing it. 'priscum… honorem', 'ancient honour', in apposition to the gate: it is a monument to her. 'vatis fatidicae', 'the fate-speaking seer', in apposition to 'Carmentis'; her name was connected with 'carmen', a song or prophecy. 'futuros Aeneadas magnos', 'the Aeneadae, great in the future', the descendants of Aeneas, the Romans; 'Ae-' is one syllable, and 'Aeneadas' is 'Ae-ne-a-das' with the 'e' short. 'Pallanteum', Evander's town, named after his Arcadian ancestor Pallas (8.51–54); it is four syllables, 'Pal-lan-te-um', and fills the last two feet, with a spondee in the fifth foot, a weighty Greek line-ending. No elisions."""),
(344, 'Lycaei.',
 "Hence a grove huge, which Romulus the fierce into an Asylum\nturned, and under the cold rock he shows the Lupercal,\nfrom Parrhasian named, of Pan, after the custom, Lycaean.",
 "Next he shows the great grove that fiery Romulus made into a sanctuary, and under the chill rock the Lupercal, named after the fashion of Arcadia for Pan of Mount Lycaeus.",
 """'Hinc', 'next', 'from here'. 'lucum ingentem', object of 'monstrat' in the next line, which governs both this and 'Lupercal'. 'quem Romulus acer Asylum rettulit', 'which bold Romulus made into an Asylum': Romulus opened a refuge on the Capitol where outlaws and runaways could settle, to people his new city (Livy 1, from memory). 'rettulit' (from 'refero') is taken here as 'turned into', 'made over as'; others take it as 'restored', as though the grove had already been a refuge in Evander's day. 'gelida… sub rupe', 'under the cold rock', the cave at the foot of the Palatine where the she-wolf suckled the twins. 'Lupercal', the cave and shrine of the Luperci, whose February rite was Rome's own. 'Parrhasio… Lycaei', 'Parrhasian (= Arcadian) Lycaean', framing the line around 'Panos', the Greek genitive of 'Pan': Pan was worshipped on Mount Lycaeus in Arcadia, and 'Lycaeus' was linked with Greek 'lykos', 'wolf', as 'Lupercal' with Latin 'lupus'. 'dictum… de more', 'named after the custom (of)'. Elision 'luc(um) ingentem'."""),
(346, 'Argi.',
 "Also and of sacred he shows the grove, Argiletum,\nand calls the place to witness, and of the death tells of his guest Argus.",
 "He shows him too the grove of the holy Argiletum, and calls the place to witness, and tells how Argus, once his guest, met his death.",
 """'Nec non et', 'and not not, also', 'and also', a strengthened connective. 'sacri… nemus Argileti', 'the grove of the sacred Argiletum', framing the line; the Argiletum was later a street of booksellers running down into the Forum. The name was explained as 'Argi letum', 'the death of Argus', and that etymology is what 346 acts out. The story (told by Servius, from memory) was that Argus, a guest of Evander, plotted against him and was killed by Evander's men without his knowledge; Evander buried him and made the place sacred. 'testatur locum', 'calls the place to witness', that he had no part in the killing of a guest, a grave crime. 'hospitis Argi', 'of his guest Argus'. 'sacri' has its first syllable long before 'cr', and the line ends in a spondaic fifth foot, 'Ar-gī', before 'lē-tī'. Elision 'loc(um) et'."""),
(348, 'dumis.',
 "Hence to the Tarpeian seat and the Capitol he leads,\ngolden now, once with woodland bristling thickets.",
 "From there he leads him to the Tarpeian seat and the Capitol, golden now, but then rough with tangled woodland thorn.",
 """'Tarpeiam sedem', 'the Tarpeian seat', the Capitoline, named for Tarpeia, who betrayed the citadel to the Sabines; from the Tarpeian Rock traitors were later thrown. 'Capitolia', the poetic plural, the hill of Jupiter's great temple. 'aurea nunc', 'golden now', in Virgil's own day, when the temple of Jupiter had a gilded roof; 'olim', 'once', in Evander's. 'silvestribus horrida dumis', 'bristling with woodland thickets', 'horrida' from 'horreo', 'stand on end', of a rough, shaggy surface. The contrast of then and now runs through the whole walk; this line puts it most plainly. Elision 'sed(em) et'."""),
(350, 'tremebant.',
 "Already then religious awe the timid terrified rustics,\ndread, of the place; already then the wood and the rock they trembled at.",
 "Even then the dread holiness of the place struck fear into the timid country people; even then they trembled at that wood and that rock.",
 """'Iam tum… iam tum', 'already then… already then', anaphora: the place was holy before there was a temple on it. 'religio… dira loci', 'the dread sanctity of the place', 'religio' the sense of a divine presence and the awe it brings, split across the line from 'dira'. 'pavidos… agrestis', 'the timid country folk', accusative plural in '-is', framing 'terrebat'. 'tremebant', 'they trembled at', transitive, with 'silvam saxumque' as object: the wood and the Tarpeian rock. No elisions."""),
(352, 'deus:',
 "“This grove, this, he says, with leafy summit, hill\n(which god is uncertain) inhabits a god:",
 "“This grove,” he said, “this hill with its leafy crown, is the dwelling of a god, though which god no one knows;",
 """Evander speaks again. Greenough sets 'inquit', 'he says', inside the speech without closing and reopening the speech marks, his habit (as at 7.594 and 8.122); read 'Hoc nemus, hunc,” inquit, “frondoso…'. 'Hoc nemus, hunc… collem', 'this grove, this hill', both objects of 'habitat', 'inhabits'. 'frondoso vertice', 'with leafy top', ablative of description. '(quis deus incertum est)', 'which god it is is uncertain', an indirect question with the verb left out, set in parentheses. 'habitat deus', 'a god dwells (here)', the noun repeated from the parenthesis. Seneca quotes this line in his letters to describe the awe of a deep grove (Letter 41, from memory). Elision 'incert(um) est'."""),
(354, 'cieret.',
 "the Arcadians himself\nbelieve they have seen Jupiter, when often the darkening\naegis he shook with his right hand and storm-clouds roused.",
 "the Arcadians believe they have seen Jupiter himself, often, shaking the dark aegis in his right hand and stirring up the storm-clouds.",
 """'Arcades', 'the Arcadians', Evander's people. 'ipsum… Iovem', 'Jupiter himself', framing 'credunt se vidisse', 'believe that they have seen', accusative and infinitive. 'cum saepe… concuteret… cieret', 'when he often shook… and roused', 'cum' with the imperfect subjunctive of the circumstances. 'nigrantem aegida', 'the darkening aegis', 'aegida' a Greek accusative; the aegis is the storm-shield of Zeus in Homer, which he shakes to send thunder and terror (Iliad 17, from memory). 'dextra', ablative, 'with his right hand'. 'nimbos', 'storm-clouds'. The hill will be the Capitol, and the god Capitoline Jupiter. No elisions."""),
(356, 'virorum.',
 "These two besides, with thrown-down walls, towns,\nremnants and of men of old you see the memorials.",
 "These two towns, too, with their walls in ruins, are what you see left of men of old, their remains and their memorials.",
 """'Haec duo… oppida', 'these two towns', framing 'praeterea disiectis', with 'disiectis… muris', ablative of description, 'with walls thrown down'. 'disiectis' is 'dis-iec-tis', the 'i' after the prefix a consonant. 'reliquias… monimenta', in apposition to 'oppida', 'as remains and memorials'; 'vides', 'you see', the guest addressed directly. 'reliquias' has its first syllable long (often spelled 'relliquias'), 'rē-li-qui-as'. 'veterum… virorum', 'of men of old', framing the clause. No elisions."""),
(357, 'arcem:',
 "This father Janus, this Saturn founded citadel:",
 "One of these citadels father Janus founded, the other Saturn:",
 """'Hanc… hanc', 'this one… that one', anaphora, both with 'arcem', 'citadel', held to the end. 'Ianus pater', 'father Janus', the old Italian god of gates and beginnings, two-faced, here an early king of the land. 'Saturnus', the god of 319. 'condidit', singular, with each subject in turn. No elisions."""),
(358, 'nomen.”',
 "Janiculum to the one, to the other had been Saturnia the name.”",
 "Janiculum was the name of the one, and Saturnia of the other.”",
 """'huic… illi', 'to this one… to that one', datives of possession with 'fuerat… nomen', 'had been the name'. The Janiculum, named for Janus, is the ridge across the Tiber; Saturnia, Saturn's town, was the old name given to a settlement on the Capitol. 'fuerat', pluperfect, 'had been', before it fell into ruin. Evander's speech ends here, and Greenough closes the mark. Elision 'Ianicul(um) huic'."""),
(361, 'Carinis.',
 "With such among themselves words, to the house they came up,\nof poor Evander, and everywhere herds they saw\nin the Roman Forum and in the elegant lowing Carinae.",
 "Talking in this way among themselves they drew near to the house of Evander, a poor man, and saw cattle everywhere, lowing in what would be the Roman Forum and the fine streets of the Carinae.",
 """'Talibus inter se dictis', ablative absolute, 'such things being said among them'. 'ad tecta subibant', 'were coming up to the house', 'tecta', 'roofs', for the dwelling. 'pauperis Euandri', 'of poor Evander', framing the line's beginning: the king is poor, and that is his glory (see 364–365). 'Euandri' has 'Eu-' as one syllable. 'passim', 'everywhere', 'here and there'. 'armenta… mugire', accusative and infinitive with 'videbant', 'saw herds lowing'. 'Romano… foro', 'in the Roman Forum', 'et lautis… Carinis', 'and in the elegant Carinae', locative ablatives: the Carinae, 'the Keels', was a smart residential quarter on the slope of the Esquiline in Virgil's time. The cattle graze where the centre of the world's capital will stand. Elisions 'passimqu(e) armenta', 'for(o) et'."""),
(363, 'cepit.',
 "When it was come to the dwelling: “This, he says, threshold the victor\nAlcides entered, this him palace received.",
 "When they reached the house he said: “Through this door Alcides passed in his triumph; this palace took him in.",
 """'Ut ventum ad sedes', 'when it was come to the dwelling', the impersonal passive 'ventum (est)', 'they came', with the auxiliary left out. Again Greenough keeps 'inquit' inside the speech marks; read '“Haec,” inquit, “limina…'. 'Haec… limina', 'this threshold', plural for singular. 'victor', 'victorious', fresh from killing Cacus. 'Alcides', 'descendant of Alcaeus', Hercules. 'subiit', 'came under', 'entered', its last syllable long, the old long '-īt' of the perfect (from '-ivit'). 'haec… regia', 'this palace', said of a humble house: the greatest of heroes was content with it. Elision 'vent(um) ad'."""),
(365, 'egenis.”',
 "Dare, guest, to despise wealth, and yourself also worthy\nfashion of the god, and to our affairs come not harsh, needy.”",
 "Have the courage, my guest, to hold riches cheap; shape yourself too to be worthy of the god, and do not look with scorn on our poor estate.”",
 """A famous couplet, quoted more than once by Seneca (Letters 18 and 31, from memory). 'Aude… contemnere opes', 'dare to despise wealth', 'aude' imperative of 'audeo'. 'hospes', 'guest', vocative. 'te quoque dignum finge deo', 'mould yourself too (as) worthy of the god', 'deo' ablative with 'dignum'; the god is Hercules, who entered this house, and who won his godhead by toil. 'rebus… egenis', 'to our needy circumstances', dative with 'veni', 'come', the imperative of 'venio'. 'non asper', 'not harsh', not disdainful, an understatement. Evander's speech ends, and Greenough closes the mark. Elisions 'Aud(e) hospes', 'contemner(e) opes'."""),
(368, 'ursae.',
 "He spoke, and of his narrow beneath the gables house\nthe huge Aeneas he led, and on strewn placed him\nsupported, leaves and the hide of a Libyan she-bear.",
 "So he spoke, and under the roof-beams of his narrow house he led the mighty Aeneas, and set him to rest on a bed of strewn leaves and the hide of a Libyan bear.",
 """The print has 'dixit', lowercase after the full stop and closing mark that end 365, a misprint for 'Dixit', corrected here; t keeps the print, because t must match the pinned source; l and i begin with a capital. 'angusti… tecti', 'of the narrow house', framing 'subter fastigia', 'beneath the gables', with the preposition 'subter' before its noun. 'ingentem Aenean', 'huge Aeneas', set against 'angusti': the hero is too big for the poor house, and the house is the better for it. 'Aenean' again 'Ae-ne-an', the '-em' of 'ingentem' elided before it. 'stratis… foliis', 'on strewn leaves', with 'effultum', 'propped up', 'resting' (from 'effulcio'). 'pelle Libystidis ursae', 'the skin of a Libyan she-bear', 'Libystis', '-idis', a Greek feminine adjective. Elision 'ingent(em) Aenean'."""),
(369, 'alis.',
 "Night rushes on and with dusky the earth embraces wings.",
 "Night came rushing in and held the earth in the embrace of her dark wings.",
 """A new paragraph in Greenough, and a new scene. 'Nox ruit', 'night rushes on', night falling fast as in the south; the phrase has a Homeric ring (Night 'swift' in Homer). 'fuscis… alis', 'with dusky wings', framing 'tellurem amplectitur': Night is pictured as a winged goddess. The verb 'amplectitur', 'embraces', prepares for the embrace of Venus and Vulcan that follows. Elision 'tellur(em) amplectitur'."""),
(373, 'amorem:',
 "But Venus, not in mind without cause terrified, the mother,\nboth by the Laurentines' threats and by the harsh moved uproar,\nVulcan addresses, and in the bedroom these words of her husband, golden,\nbegins, and into her words divine breathes love:",
 "But Venus, a mother with good cause for fear in her heart, alarmed by the threats of the Laurentines and their fierce uproar, turned to Vulcan, and in her husband's golden chamber began to speak, breathing divine love into her words:",
 """'At', marking the change of scene, from earth to heaven. 'haud… nequiquam', 'not in vain', 'not without reason', a double negative making a strong positive. 'animo… exterrita', 'terrified in mind'; 'mater', 'the mother', placed last: it is as Aeneas's mother that she is afraid. 'Laurentumque minis', 'by the threats of the Laurentines', 'Laurentum', genitive plural of 'Laurentes' (the shorter form of 'Laurentium'), the people of Latinus. 'duro… tumultu', 'by the harsh uproar', the call to arms of Book VII. 'Volcanum', Greenough's spelling of 'Vulcanum', the smith-god, Venus's husband. 'thalamo… coniugis aureo', 'in the golden chamber of her husband', framing 'haec'; 'aureo' is two syllables by synizesis, 'au-reo', and 'coniugis' is 'con-iu-gis', the 'i' a consonant. 'adspirat', Greenough's spelling of 'aspirat', 'breathes into', with dative 'dictis'. Elisions 'nequiqu(am) exterrita', 'Volcan(um) adloquitur', 'thalamoqu(e) haec', 'divin(um) adspirat'."""),
(378, 'labores,',
 "“While in war the Argive were laying waste Pergamum kings,\nowed and destined to fall to hostile fires citadels,\nnot any help for the wretched, not arms did I ask\nof your art and power, nor you, dearest husband,\nor in vain your did I wish to put to work labours,",
 "“While the Argive kings were laying waste to Pergamum in war, its towers doomed to fall to their enemies' fire, I asked for no help for those poor people, no weapons made by your skill and power; I would not set you, my dearest husband, or your labours, to work in vain,",
 """Venus's speech opens with the past: she did not ask for help when Troy fell. 'Dum… vastabant', 'while they were laying waste', 'dum' with the imperfect of a lasting action. 'Argolici… reges', 'the Argive kings', the Greek chiefs, framing the line. 'Pergama', 'Pergamum', the citadel of Troy, neuter plural. 'debita', 'owed', due to fate; 'casuras… arces', 'citadels destined to fall', the future participle; 'inimicis ignibus', 'to hostile fires', dative with 'casuras' or ablative of means. 'non ullum… non arma', anaphora: 'no help at all, no arms'. 'rogavi', 'I asked', with 'auxilium miseris', 'help for the wretched' (the Trojans), and 'arma artis opisque tuae', 'arms of your art and power'. 'nec te… incassumve tuos… exercere labores', 'nor (did I wish) to set you, or your labours, to work in vain': both 'te' and 'labores' are objects of 'exercere'. 'coniunx' is two syllables, 'con-iunx'. Elisions 'bell(o) Argolici', 'casurasqu(e) inimicis', 'ull(um) auxilium', 'volu(i) exercere'."""),
(380, 'laborem.',
 "although both to Priam I owed very much, to his sons,\nand the hard of Aeneas I had wept for often labour.",
 "though I owed so much to the sons of Priam, and had often wept over the cruel sufferings of Aeneas.",
 """'quamvis', 'although', with the subjunctive 'deberem' and 'flevissem'. 'Priami… natis', 'to Priam's sons', dative with 'deberem', framing 'deberem plurima', 'I owed very many things': Venus owed Troy a debt, since Paris, Priam's son, gave her the golden apple. 'durum… laborem', 'the hard toil', framing 'Aeneae flevissem saepe'; 'Aeneae', genitive, 'Ae-ne-ae', three syllables. 'labores… laborem', the same word ending two successive lines, first Vulcan's work, then Aeneas's suffering. Elision 'dur(um) Aeneae'."""),
(381, 'oris:',
 "Now by Jupiter's commands, of the Rutulians he has taken his stand on the shores:",
 "Now, at Jupiter's command, he has set foot on the shores of the Rutulians;",
 """'Nunc', 'now', against the 'Dum' of 374. 'Iovis imperiis', 'by the commands of Jupiter', ablative of cause: Venus stresses that Aeneas is in Italy by Jupiter's will, not his own. 'constitit', 'has taken his stand', 'has settled', the subject Aeneas, from 380. 'Rutulorum… oris', 'on the shores of the Rutulians', Turnus's people, standing for Italy. No elisions."""),
(383, 'nato.',
 "therefore I, the same, a suppliant come, and the holy to me power,\narms I ask, a mother for her son.",
 "and so I, who never asked before, come as a suppliant to the divine power I hold sacred, and beg for arms, a mother for her son.",
 """'ergo', 'therefore'. 'eadem', 'the same (woman)', 'I who before asked nothing'. 'supplex venio', 'I come as a suppliant'. 'sanctum mihi numen', 'your power, holy to me', the person asked, with 'arma', the thing asked, both accusatives with 'rogo' (verbs of asking take two accusatives). 'genetrix nato', 'a mother for her son', the two words side by side, the plea in brief; 'nato', dative of advantage. Elisions 'erg(o) eadem', 'veni(o) et'."""),
(384, 'coniunx.',
 "You the daughter of Nereus,\nyou could with tears the Tithonian bend, wife.",
 "You let yourself be moved by the tears of Nereus's daughter, and of the wife of Tithonus.",
 """'Te… te', anaphora: 'you… you (were the one whom they could move)'. 'filia Nerei', 'the daughter of Nereus', Thetis, who got from Hephaestus (Vulcan) the arms of Achilles (Iliad 18). 'Nerei' is two syllables, 'Ne-rei', the '-ei' run together by synizesis. 'Tithonia… coniunx', 'the Tithonian wife', Aurora, the Dawn, wife of Tithonus, who got arms from Vulcan for her son Memnon; that story was told in the lost epic of the Trojan cycle, not in Homer (from memory). 'potuit… flectere', 'was able to bend (you)', singular with each subject. 'lacrimis', 'with tears', ablative of means. The argument is pointed: if Vulcan made arms for the sons of other wives, he can make them for his own wife's son. No elisions."""),
(386, 'meorum.”',
 "See what come together peoples, what walls with closed\nsharpen steel gates against me and the destruction of my own.”",
 "Look what peoples are gathering, what cities have shut their gates and are whetting the sword against me and the destruction of my own.”",
 """'Aspice', 'look', imperative. 'qui coeant populi', 'what peoples are coming together', and 'quae moenia… ferrum acuant', 'what walls are sharpening steel', indirect questions with the subjunctive. 'coeant' is three syllables, 'co-e-ant'. 'moenia', 'walls', for the cities they enclose. 'clausis… portis', ablative absolute, 'with gates closed', framing 'ferrum acuant'. 'in me', 'against me', Venus making her son's danger her own. 'exscidium', Greenough's spelling of 'excidium', 'destruction'. 'meorum', 'of my own', the Trojans. Venus's speech ends, and Greenough closes the mark. Elisions 'ferr(um) acuant', 'm(e) exscidiumque'."""),
(388, 'fovet.',
 "She had spoken, and with snowy from this side and that, the goddess, arms\nhim hesitating, in an embrace soft she warms.",
 "She had finished speaking; and as he hesitated, the goddess threw her snow-white arms about him on either side and warmed him in her soft embrace.",
 """'Dixerat', pluperfect, 'she had spoken', a common way to close a speech and move on. 'niveis… lacertis', 'with snowy arms', framing the clause. 'hinc atque hinc', 'on this side and on that', both arms about him. 'diva', 'the goddess'. 'cunctantem', 'him hesitating', object of 'fovet': Vulcan has not yet answered. 'amplexu molli', 'in a soft embrace', ablative of means. 'fovet', 'warms', 'cherishes', present tense, quickening the scene. Elisions 'atqu(e) hinc', 'cunctant(em) amplexu'."""),
(390, 'cucurrit:',
 "He suddenly\nreceived the accustomed flame, and the known the marrow\nentered heat and through his loosened bones ran:",
 "At once the flame he knew so well took hold of him; the familiar heat sank into his very marrow and ran through his melting frame:",
 """'Ille', 'he', Vulcan. 'repente', 'suddenly'. 'accepit solitam flammam', 'caught the accustomed flame', the fire of love, and fire is the smith-god's element. 'notus… calor', 'the familiar heat', framing 'medullas intravit', 'entered his marrow', the seat of passion in Latin love poetry. 'labefacta per ossa', 'through his loosened bones', 'labefacta' from 'labefacio', 'make to totter', 'weaken'. No elisions."""),
(392, 'nimbos.',
 "not otherwise than at times, when by thunder burst open, flashing,\na fiery rift, gleaming, runs through with light the storm-clouds.",
 "just as sometimes, when the thunder breaks, a fiery fissure splits the storm-clouds with its quivering light.",
 """A simile drawn from Vulcan's own element: lightning. 'non secus atque', 'not otherwise than', 'just as'. 'olim', 'at times', the use of 'olim' in similes for what happens now and then. 'tonitru… corusco', 'by the flashing thunder', ablative of cause, framing 'cum rupta': the thunder and lightning are one stroke. 'rupta', 'burst open', with 'ignea rima', 'a fiery crack', the lightning seen as a rift in the cloud. 'micans', 'flashing'. 'percurrit… nimbos', 'runs through the storm-clouds', 'lumine', 'with its light'. The flame of 389 is now a stroke across the sky. Elision 'atqu(e) olim'."""),
(393, 'coniunx.',
 "Felt it, glad in her wiles and of her beauty aware, the wife.",
 "His wife felt it, pleased with her artful scheme and well aware of her beauty.",
 """'Sensit', 'she felt it', the effect of her embrace, placed first. 'laeta dolis', 'glad in her wiles', 'dolis' ablative of cause: the request was made with calculation. 'formae conscia', 'conscious of her beauty', 'formae' genitive with an adjective of knowing. 'coniunx', 'the wife', held to the end, as 'mater' at 370: Venus works as a wife on behalf of a son who is not her husband's. The scene recalls Hera's seduction of Zeus in Iliad 14 (from memory). No elisions."""),
(394, 'amore:',
 "Then the father with eternal speaks, bound fast, love:",
 "Then the fire-god, bound fast by undying love, spoke:",
 """'pater', 'father', a title of honour for a god, as 'pater Ianus' at 357; here Vulcan (Mulciber, 'father Lemnius' elsewhere). 'aeterno… devinctus amore', 'bound fast by eternal love', framing 'fatur', 'speaks', ablative of means. 'devinctus', 'tied down', 'captivated', from 'devincio'. No elisions."""),
(395, 'alto?',
 "“Why reasons do you seek from the deep?",
 "“Why do you go so far back for reasons?",
 """Vulcan's reply opens here and runs to 404. 'causas', 'reasons', 'pleas', the arguments Venus has brought. 'ex alto', 'from the depth', 'from far off': her history of the Trojan war, her debt to Priam's sons, Thetis and Aurora. The question means 'you need not argue'. No elisions."""),
(396, 'mei?',
 "Your confidence has gone\nwhither, goddess, in me?",
 "Where has your trust in me gone, my goddess?",
 """'Fiducia… mei', 'confidence in me', 'mei' the objective genitive of 'ego', framing 'cessit quo tibi, diva'. 'quo', 'whither', 'to where', placed second in its clause, after the verb. 'tibi', dative of reference, 'for you', 'your'. 'cessit', 'has withdrawn', 'has gone'. 'diva', vocative, 'goddess', an affectionate address. No elisions."""),
(397, 'fuisset:',
 "Like if care had been,\nthen too right for us the Teucrians to arm it would have been:",
 "Had you shown the same concern then, it would have been allowed me even then to arm the Trojans;",
 """'Similis si cura fuisset', 'if a like concern had been (yours)', the pluperfect subjunctive of a past unreal condition, and 'fas… fuisset', 'it would have been right', in the main clause: the same verb ends both lines. 'tum quoque', 'then too', at Troy. 'fas', 'what is allowed by divine law', with 'nobis', 'for us', the royal plural for 'me'. 'Teucros', 'the Teucrians', the Trojans, after their ancestor Teucer; Greek 'eu' is one syllable, 'Teu-cros'. 'armare', 'to arm', the business in hand. No elisions."""),
(399, 'annos.',
 "neither the father all-powerful Troy nor the fates forbade\nto stand, and ten other Priam to survive through years.",
 "neither the almighty Father nor the fates forbade Troy to stand, or Priam to live on for ten years more.",
 """'nec… nec', 'neither… nor'. 'pater omnipotens', 'the almighty father', Jupiter. 'vetabant', imperfect, 'were not forbidding': the city's fall was fixed, but its date was not. 'Troiam… stare', 'Troy to stand', accusative and infinitive with 'vetabant'. 'decemque alios… per annos', 'through ten more years', framing 'Priamum superesse', 'Priam to survive'. Vulcan's claim is a bold one: fate could have been put off, though not undone, a view of fate the poem takes elsewhere too (Juno at 7.315). Elision 'decemqu(e) alios'."""),
(402, 'electro,',
 "And now, if to make war you are preparing, and this to you the mind is,\nwhatever in my art I can promise of care,\nwhatever made can be with iron or with molten electrum,",
 "And now, if you are making ready for war and this is your purpose, whatever care I can promise in my craft, whatever can be wrought in iron or in molten electrum,",
 """A comma-ended unit: the sentence runs on through 404, and 'absiste' (403) is its main verb; the units are split here because the closing speech mark at 404 is printed joined to the next word, so the last unit must also carry the narrative to 406. 'Et nunc', 'and now', against 'tum' at 397. 'si bellare paras', 'if you are preparing to wage war'. 'haec tibi mens est', 'this is your mind', dative of possession, 'you have this purpose'. 'quidquid… curae', 'whatever of care', partitive genitive: 'all the care I can promise in my art'. 'quod fieri… potest', 'what can be made', 'with iron or molten electrum', ablatives of material. 'electrum', an alloy of gold and silver, also amber; here the metal. The line ends with a spondaic fifth foot, 'po-test ē-lec-trō'. These clauses are the objects of a promise that Vulcan leaves unstated; the main verb comes in 403. Elision 'atqu(e) haec'."""),
(406, 'soporem.',
 "as much as fires and breaths avail — cease by entreating\nto doubt your strength.” These words having spoken,\nthe longed-for he gave embraces, and calm he sought,\nof his wife poured into the lap, through his limbs, sleep.",
 "all that fire and the breath of the bellows can achieve — stop doubting your power by pleading with me.” With these words he gave her the embrace she longed for, and, sinking into his wife's lap, let quiet sleep steal through all his limbs.",
 """The print has 'tuis. ”Ea', with a space before the closing mark and none after it, a misprint for 'tuis.” Ea', corrected here; t keeps the print, because t must match the pinned source. Because the mark is joined to 'Ea', this unit also carries 'Ea verba locutus… soporem', as at 7.560 and 7.599. 'quantum ignes animaeque valent', 'as much as fires and breaths can do', 'animae', the blasts of the bellows. 'absiste precando… indubitare', 'cease by pleading to doubt', 'stop doubting your power by begging': 'precando', the ablative of the gerund; 'indubitare', 'to doubt about', a rare verb, with the dative 'viribus… tuis' (L&S, from memory). Vulcan's speech ends. 'Ea verba locutus', 'having spoken these words', 'locutus' perfect participle of the deponent 'loquor'. 'optatos… amplexus', 'the longed-for embraces', framing 'dedit'. 'placidum… soporem', 'calm sleep', framing the sentence across two lines. 'coniugis infusus gremio', 'poured into his wife's lap', 'gremio' dative with the compound participle, the body relaxing into sleep after love. 'coniugis' is again 'con-iu-gis'. Elision 'quant(um) ignes'."""),
]

P = A.part('aeneid-060'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
